/* ============================================================
   Teorema: navigarea principală a unui cont conectat, cu 7 taburi. Pe telefon (până la 600px) e bara de jos, doar cu poze;
   de la 601px în sus e panoul din stânga (poză și nume; sub 1180px doar poze), cu sigla deasupra taburilor.
   Rulează în <head>, deci e acolo din primul cadru. Stilurile sunt în css/bnav.css, după clasele html.bm-authed / bm-guest
   puse de auth-hint.js. Cine nu e conectat păstrează navbarul de sus.
   Taburile sunt pagini aparte: Învață, Exerciții, Simulare, Antrenament, Clase, Misiuni, Profil.
   ============================================================ */
(function () {
  'use strict';
  var TABS = [
    ['invata', 'parcurs.html', 'Învață'],
    ['exercitii', 'capitole.html', 'Exerciții'],
    ['simulare', 'bac.html?new=1', 'Simulare'],
    ['antrenament', 'training.html', 'Antrenament'],
    ['clase', 'classes.html', 'Clase'],
    ['misiuni', 'misiuni.html', 'Misiuni'],
    ['profil', 'profile.html', 'Profil']
  ];
  /* imaginile sunt chiar în script (data URI), ca să existe din primul cadru: fără sclipire la reîncărcare. Se regenerează din assets/images/tabs/ cu scripts/prebake-bnav-icons.js */
  var ICON = {
    'profil': 'data:image/svg+xml;base64,',
    'invata': 'data:image/svg+xml;base64,',
    'exercitii': 'data:image/svg+xml;base64,',
    'simulare': 'data:image/svg+xml;base64,',
    'antrenament': 'data:image/svg+xml;base64,',
    'clase': 'data:image/svg+xml;base64,',
    'misiuni': 'data:image/svg+xml;base64,'
  };
  var BRAND = {
    'logo': 'data:image/svg+xml;base64,',
    'mark': 'data:image/svg+xml;base64,'
  };
  var PAGE = {
    'profile': 'profil', 'parcurs': 'invata', 'capitole': 'exercitii', 'category': 'exercitii', 'adauga-exercitiu': 'exercitii',
    'bac': 'simulare', 'training': 'antrenament', 'classes': 'clase', 'class': 'clase', 'misiuni': 'misiuni'
  };
  var file = (location.pathname.split('/').pop() || 'index.html').toLowerCase().replace(/\.html$/, '');
  var active = PAGE[file] || '';
  /* pe Invata, butonul Sectiuni si inelul de progres din randul de sus apar din primul cadru (ultima valoare e tinuta de js/parcurs/path.js) */
  if (file === 'parcurs') {
    var de0 = document.documentElement;
    de0.setAttribute('data-pp', '1');
    try { var pc0 = parseInt(localStorage.getItem('bm_pp_pct'), 10); if (pc0 >= 0) { de0.setAttribute('data-pp-pct', String(pc0)); de0.style.setProperty('--pp-deg', Math.round(pc0 * 3.6) + 'deg'); } } catch (e) { /* ignore */ }
  }
  var idx = -1, i;
  for (i = 0; i < TABS.length; i++) if (TABS[i][0] === active) idx = i;

  var prev = -1;
  try { prev = parseInt(sessionStorage.getItem('bnav_prev'), 10); if (isNaN(prev)) prev = -1; if (idx >= 0) sessionStorage.setItem('bnav_prev', String(idx)); } catch (e) { /* ignore */ }

  function build() {
    var nav = document.createElement('nav');
    nav.id = 'bnav'; nav.setAttribute('aria-label', 'Navigare principală');
    var h = '<i class="bn-ind" aria-hidden="true"></i>';
    /* sigla stă doar în panoul lateral (laptop și tabletă); pe telefon bara e doar cu poze */
    h += '<a class="bn-brand" href="parcurs.html" aria-label="Teorema"><img class="bn-logo" src="' + BRAND.logo + '" alt="Teorema" decoding="sync"><img class="bn-mark" src="' + BRAND.mark + '" alt="" decoding="sync"></a>';
    TABS.forEach(function (t, n) {
      h += '<a class="bn-b' + (n === idx ? ' on' : '') + '" href="' + t[1] + '" data-tab="' + t[0] + '" aria-label="' + t[2] + '" title="' + t[2] + '"' + (n === idx ? ' aria-current="page"' : '') + '>' +
        '<img src="' + ICON[t[0]] + '" alt="" width="34" height="34" decoding="sync"><span class="bn-t">' + t[2] + '</span></a>';
    });
    nav.innerHTML = h;
    var ind = nav.firstChild;
    var from = prev >= 0 && prev !== idx ? prev : idx;
    nav.style.setProperty('--i', String(Math.max(0, from)));
    if (idx < 0) nav.classList.add('bn-none');
    document.body.appendChild(nav);
    if (from !== idx && idx >= 0) {
      /* alunecă de la tabul pe care erai la cel nou (doar pe telefon; în panoul lateral tabul curent e aprins direct) */
      requestAnimationFrame(function () { requestAnimationFrame(function () { nav.style.setProperty('--i', String(idx)); ind.classList.add('go'); }); });
    }
  }

  function put() {
    if (!document.body) return false;
    if (!document.getElementById('bnav')) build();
    return true;
  }
  if (!put()) {
    var mo = new MutationObserver(function () { if (put()) mo.disconnect(); });
    mo.observe(document.documentElement, { childList: true });
  }

  /* în sala de examen (Simulare) bara dispare, ca să nu încurce */
  document.addEventListener('DOMContentLoaded', function () {
    var ex = document.getElementById('examView');
    if (!ex) return;
    var de = document.documentElement;
    var sync = function () { de.classList.toggle('bnav-off', getComputedStyle(ex).display !== 'none'); };
    new MutationObserver(sync).observe(ex, { attributes: true, attributeFilter: ['style', 'class'] });
    sync();
  });
})();
